function calloutCenter(item){if(Array.isArray(item.points)&&item.points.length){return{x:item.points.reduce((sum,p)=>sum+p.x,0)/item.points.length,y:item.points.reduce((sum,p)=>sum+p.y,0)/item.points.length}}return{x:item.x,y:item.y}}
