function battleUnits(side,color){let units=[];(side?.infantry||[]).forEach(([x,y])=>units.push({type:'unit',unit:'person',points:[{x,y}],color,width:5}));(side?.vehicles||[]).forEach(([x,y,unit])=>units.push({type:'unit',unit,points:[{x,y}],color,width:5}));return units}
function drawBattleOverlay(ctx){if(current!==window.DELTAMAP_BATTLE?.map||!battlePoint)return;let round=window.DELTAMAP_BATTLE.rounds[battleRound];ctx.save();ctx.strokeStyle='#ffffff';ctx.lineWidth=3;ctx.setLineDash([10,7]);ctx.shadowColor='#000';ctx.shadowBlur=5;ctx.beginPath();battlePoint.front.forEach((point,index)=>{let p=w2s({x:point[0],y:point[1]});index?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)});ctx.stroke();ctx.restore();battleUnits(battlePoint.attack,round.attackColor).forEach(unit=>drawObject(ctx,unit));battleUnits(battlePoint.defense,round.defenseColor).forEach(unit=>drawObject(ctx,unit));drawBattleLabel(ctx,battlePoint.attack,round.attack,round.attackColor);drawBattleLabel(ctx,battlePoint.defense,round.defense,round.defenseColor)}
function drawBattleLabel(ctx,side,name,color){let all=[...(side.infantry||[]),...(side.vehicles||[])];if(!all.length)return;let x=all.reduce((sum,p)=>sum+p[0],0)/all.length,y=all.reduce((sum,p)=>sum+p[1],0)/all.length,p=w2s({x,y});ctx.save();ctx.font='700 12px "Microsoft YaHei",sans-serif';let label=`${name} ${side.infantry.length}人 / ${side.vehicles.length}载具`,tw=ctx.measureText(label).width;ctx.fillStyle='#0a0c09df';ctx.fillRect(p.x-tw/2-6,p.y-42,tw+12,24);ctx.strokeStyle=color;ctx.strokeRect(p.x-tw/2-6,p.y-42,tw+12,24);ctx.fillStyle=color;ctx.fillText(label,p.x-tw/2,p.y-25);ctx.restore()}
function battleTime(seconds){let value=Math.max(0,Number(seconds)||0);return`${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`}
function selectBattlePoint(time){let round=window.DELTAMAP_BATTLE?.rounds?.[battleRound];if(!round)return;let best=round.points[0];round.points.forEach(point=>{if(point.time<=time)best=point});battlePoint=best;$("#battleClock").textContent=`回合 ${battleTime(time)} · 视频 ${battleTime(best.videoTime)}`;$("#battleSummary").textContent=`${round.attack} 进攻 / ${round.defense} 防守`;$("#battleAttackStats").style.color=round.attackColor||'#42a5ff';$("#battleDefenseStats").style.color=round.defenseColor||'#ffb43b';$("#battleAttackStats").textContent=`${round.attack} 兵力 ${best.attackForce}`;$("#battleDefenseStats").textContent=`${round.defense} 兵力 ${best.defenseForce}`;$("#battleObjectives").innerHTML=(best.objectives||[]).map(objective=>{let owner=objective.owner==='attack'?(round.attackColor||'#42a5ff'):objective.owner==='defense'?(round.defenseColor||'#ffb43b'):'#8b9387',progress=Math.max(0,Math.min(100,Number(objective.progress)||0));return`<div class="battle-objective" title="${objective.id} 占领进度 ${progress}%"><i class="battle-objective-fill" style="height:${progress}%;--owner:${owner}"></i><span>${objective.id}</span></div>`}).join('')}
function clearBattleReview(silent=false){window.DELTAMAP_BATTLE=null;battlePoint=null;battleRound=0;localStorage.removeItem('deltamap-battle-review-v1');$("#battleRounds").innerHTML='';$("#battleSummary").textContent='未导入复盘';$("#battleClock").textContent='';$("#battleAttackStats").textContent='';$("#battleDefenseStats").textContent='';$("#battleObjectives").innerHTML='';$("#battleScrubber").max=1;$("#battleScrubber").value=0;if(!silent)toast('复盘已清除')}
function renderBattleRounds(){let rounds=window.DELTAMAP_BATTLE?.rounds||[];$("#battleRounds").innerHTML=rounds.map((round,index)=>`<button class="${index===battleRound?'active':''}" data-battle-round="${index}">第 ${round.round} 轮</button>`).join('');let round=rounds[battleRound];if(!round)return clearBattleReview();$("#battleScrubber").max=round.duration;$("#battleScrubber").value=round.points[0].time;selectBattlePoint(round.points[0].time)}
async function importBattleReview(file){try{let data=JSON.parse(await file.text());if(data.schema!=='deltamap-force-review/v1'||!Array.isArray(data.rounds))throw 0;data.rounds=data.rounds.map(round=>({...round,points:Array.isArray(round.points)?round.points.filter(point=>Number.isFinite(point.attackForce)&&Number.isFinite(point.defenseForce)):[]})).filter(round=>round.points.length);if(!data.rounds.length)throw 0;window.DELTAMAP_BATTLE=data;battleRound=0;localStorage.setItem('deltamap-battle-review-v1',JSON.stringify(data));renderBattleRounds();toast('复盘 JSON 已导入')}catch{toast('没有可用的清晰兵力记录')}}
function setBattleVisible(visible){$("#battleTimeline").classList.toggle('review-hidden',!visible);$("#battleToggle").classList.toggle('battle-toggle-active',visible);$("#battleToggle").setAttribute('aria-pressed',String(visible));$("#battleToggle").title=visible?'隐藏复盘':'显示复盘';localStorage.setItem('deltamap-review-visible-v2',visible?'1':'0')}
function bindBattle(){$("#battleRounds").onclick=event=>{let button=event.target.closest('[data-battle-round]');if(!button)return;battleRound=Number(button.dataset.battleRound);renderBattleRounds()};$("#battleScrubber").oninput=event=>selectBattlePoint(Number(event.target.value));$("#importBattleReview").onclick=()=>$("#battleReviewFile").click();$("#clearBattleReview").onclick=()=>clearBattleReview();$("#battleToggle").onclick=()=>setBattleVisible($("#battleTimeline").classList.contains('review-hidden'));$("#battleReviewFile").onchange=event=>{if(event.target.files[0])importBattleReview(event.target.files[0]);event.target.value=''};setBattleVisible(localStorage.getItem('deltamap-review-visible-v2')==='1');window.DELTAMAP_BATTLE?renderBattleRounds():clearBattleReview(true)}
function pos(e){let r=drawCanvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function down(e){if(e.button!==undefined&&e.button!==0)return;if(collabReadOnly&&tool!=='hand'){toast('当前以观察者身份加入，不能编辑');return}closeMenu();hideText();if(pendingCallout)cancelCallout();let s=pos(e),world=s2w(s);pointer={id:e.pointerId,start:s,last:s,world};drawCanvas.setPointerCapture?.(e.pointerId);if(tool==='hand'){let target=!collabReadOnly&&[...objects()].reverse().find(o=>(o.type==='unit'||o.type==='gadget')&&hit(o,s));drawCanvas.classList.add('dragging');if(target){pointer.target=target;pointer.original=target.points.map(p=>({...p}))}else pointer.origin={x:view.x,y:view.y}}else if(tool==='marker'){add({type:'marker',points:[world],color,width});pointer=null}else if(tool==='unit'){add({type:'unit',unit:unitType,points:[world],color,width});pointer=null}else if(tool==='gadget'&&gadgetType==='dataKnife'){add({type:'gadget',gadget:gadgetType,points:[world],color,width});pointer=null}else if(tool==='gadget'){draft={type:'gadget',gadget:gadgetType,points:[world],angle:-Math.PI/2,color,width};draw()}else if(tool==='text'){showText(s,world);pointer=null}else if(tool==='eraser'){erase(s)}else{draft={type:tool==='callout'?'pen':tool,callout:tool==='callout',points:[world,world],color:tool==='callout'?'#50dcd2':color,width};if(tool==='pen'||tool==='callout')draft.points=[world];draw()}}
function move(e){if(!pointer||e.pointerId!==pointer.id)return;let s=pos(e);if(tool==='hand'){if(pointer.target){let dx=(s.x-pointer.start.x)/view.scale,dy=(s.y-pointer.start.y)/view.scale;pointer.target.points=pointer.original.map(p=>({x:p.x+dx,y:p.y+dy}));draw()}else{view.x=pointer.origin.x+s.x-pointer.start.x;view.y=pointer.origin.y+s.y-pointer.start.y;clamp();queue()}}else if(tool==='eraser')erase(s);else if(draft){let world=s2w(s);if(tool==='gadget')draft.angle=Math.atan2(world.y-draft.points[0].y,world.x-draft.points[0].x);else if(tool==='pen'||tool==='callout'){let last=draft.points[draft.points.length-1];if(Math.hypot(world.x-last.x,world.y-last.y)*view.scale>1.8)draft.points.push(world)}else draft.points[1]=world;draw()}pointer.last=s}
function up(e){if(!pointer||e.pointerId!==pointer.id)return;drawCanvas.classList.remove('dragging');if(pointer.target&&Math.hypot(pointer.last.x-pointer.start.x,pointer.last.y-pointer.start.y)>1){snapshot();save()}if(draft){let valid=draft.type==='gadget'||(draft.callout?draft.points.length>2:draft.type==='pen'?draft.points.length>1:Math.hypot(draft.points[1].x-draft.points[0].x,draft.points[1].y-draft.points[0].y)*view.scale>3);if(valid&&draft.callout){pendingCallout={points:draft.points.map(point=>({...point}))};showCalloutEditor(pointer.last)}else if(valid){draft.id=draft.id||uid();objects().push(draft);snapshot();save();counts()}else if(draft.callout)toast('请拖动圈出一个完整范围');draft=null;draw()}if(tool==='eraser'&&erased){snapshot();save();erased=false}pointer=null}
function add(o){o.id=o.id||uid();objects().push(o);snapshot();save();counts();draw()}
function seg(p,a,b){let dx=b.x-a.x,dy=b.y-a.y;if(!dx&&!dy)return Math.hypot(p.x-a.x,p.y-a.y);let t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy)));return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy)}
function hit(o,s){let p=(o.points||[]).map(w2s);if(!p.length)return false;if(o.type==='marker'||o.type==='text'||o.type==='unit'||o.type==='gadget')return Math.hypot(s.x-p[0].x,s.y-p[0].y)<24;if(o.type==='circle'&&p[1])return Math.abs(Math.hypot(s.x-p[0].x,s.y-p[0].y)-Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y))<15;if(o.type==='rect'&&p[1]){let minx=Math.min(p[0].x,p[1].x)-12,maxx=Math.max(p[0].x,p[1].x)+12,miny=Math.min(p[0].y,p[1].y)-12,maxy=Math.max(p[0].y,p[1].y)+12,nx=Math.abs(s.x-p[0].x)<14||Math.abs(s.x-p[1].x)<14,ny=Math.abs(s.y-p[0].y)<14||Math.abs(s.y-p[1].y)<14;return s.x>=minx&&s.x<=maxx&&ny||s.y>=miny&&s.y<=maxy&&nx}return p.slice(0,-1).some((q,i)=>seg(s,q,p[i+1])<15)}
function erase(s){for(let i=objects().length-1;i>=0;i--)if(hit(objects()[i],s)){objects().splice(i,1);erased=true;draw();counts();return}}
function select(t){tool=t;drawCanvas.dataset.tool=t;$$('.tool-btn').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$("#unitPalette").classList.toggle('open',t==='unit');$("#gadgetPalette").classList.toggle('open',t==='gadget');hideText();if(t!=='callout')cancelCallout()}
